mapper.sql:
FROM wx_external_config config
RIGHT JOIN wx_external_routes routes ON config.wx_external_config_id = routes.wx_external_config_id
WHERE config.company_id = #{companyId}

	AND config.app_id = #{appId}


	AND routes.route_info LIKE CONCAT('%', #{routeInfoNeedleEscaped}, '%')

mapper.select:
SELECT config.wx_external_config_id AS wx_external_config_id, config.app_id AS app_id, config.app_name AS app_name, config.app_desc AS app_desc, routes.wx_external_routes_id AS wx_external_routes_id, routes.route_name AS route_name, routes.route_info AS route_info, routes.route_desc AS route_desc
ORDER BY routes.wx_external_routes_id ASC
LIMIT #{limit} OFFSET #{offset}
